    picker.querySelector('.hp-animate').onclick=e=>{previewAnimated=!previewAnimated;e.currentTarget.setAttribute('aria-pressed',String(previewAnimated));e.currentTarget.textContent=previewAnimated?'Pause preview':'Animate preview';};
